Rewrite the following GNU C++ code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to rewrite:
<original_code>
﻿#include <bits/stdc++.h>
using namespace std;

#define pb push_back
#define mp make_pair
#define fs first
#define sc second
#define sz(a) ((int) (a).size())
#define int64 long long
#define ldb long double
const ldb pi = acos(-1.0);

const int N = 20;
const double eps = 1e-10;
int n, k;
double a[N], p[1 << N], res[N];

int main() {
	// assert(freopen("input.txt", "r", stdin));
	// assert(freopen("output.txt", "w", stdout));
	scanf("%d%d", &n, &k);
	int cnt = 0;
	for (int i = 0; i < n; ++i) {
		scanf("%lf", &a[i]);
		if (a[i] < eps) ++cnt;
	}
	k = min(n - cnt, k);
	p[0] = 1;
	for (int mask = 1; mask < (1 << n); ++mask) {
		double suma = 0;
		bool ok = true;
		int cnt = 0;
		for (int i = 0; i < n; ++i)
			if (mask & (1 << i)) {
				suma += a[i];
				if (a[i] < eps) ok = false;
				++cnt;
			}
		if (!ok) {
			p[mask] = 0;
			continue;
		} else {
			double sump = 0;
			for (int i = 0; i < n; ++i)
				if (mask & (1 << i))
					sump += a[i] / (1 - suma + a[i]) * p[mask ^ (1 << i)];
			p[mask] = sump;
		}
		if (cnt == k)
			for (int i = 0; i < n; ++i)
				if (mask & (1 << i))
					res[i] += p[mask];
	}
	for (int i = 0; i < n; ++i)
		printf("%.10f%c", res[i], " \n"[i == n - 1]);
	return 0;
}
</original_code>
